style.css:
@-moz-document domain("youtube.com") {
/* === Custom YouTube Progress Bar with Image === */

  /* Ensure the progress bar container is visible and positionable */
  .ytp-progress-bar-container {
    position: relative !important;
    height: 6px !important;
  }

  /* Customize the played portion */
  .ytp-play-progress {
    background: linear-gradient(90deg, #dec3eb,#dedcdc) !important;
    height: 6px !important;
    position: relative !important;
    transition: width 0.05s linear !important;
  }

  /* Add a small image that moves with the progress */
  .ytp-play-progress::after {
    content: "";
    position: absolute;
    top: -12px; /* raise it above the bar */
    right: 0; /* follows the right edge of the progress */
    width: 26px;
    height: 26px;
    background: url("https://tenor.com/rtxrNbNxDaE.gif") no-repeat center center !important;
    background-size: contain !important;
    pointer-events: none !important;
  }
}
